"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[757],{92:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-04-svm</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="c36ba7fc" class="cell markdown">\n<h1 id="лабораторная-работа--4-метод-опорных-векторов-svm-с-ядрами">Лабораторная\nработа № 4. Метод опорных векторов (SVM) с ядрами</h1>\n<p><strong>Курс:</strong> Классическое машинное обучение, 4 курс\nприкладной математики</p>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Изучить метод опорных векторов, научиться решать двойственную задачу\nи использовать ядра для нелинейной классификации.</p>\n<p><strong>Используемые инструменты:</strong>\n<code>scipy.optimize</code>, <code>sklearn.svm</code>,\n<code>matplotlib</code>, опционально <code>cvxopt</code>.</p>\n</div>\n<div id="360afd34" class="cell markdown">\n<h3 id="регламент-сдачи">Регламент сдачи</h3>\n<p>Работа сдаётся в виде этого же ноутбука, дополненного вашим кодом.\nОбязательно:</p>\n<ol>\n<li>Читаемый код с комментариями.</li>\n<li>Визуализации (графики, таблицы).</li>\n<li><strong>Текстовый вывод после каждого задания</strong> — не только\nкод, но и объяснение результата.</li>\n<li>Финальный вывод по работе.</li>\n</ol>\n<p><strong>Критерии оценки:</strong> корректность реализации — 30 %,\nкачество визуализаций и анализа — 20 %, обоснованность выводов — 20 %,\nсравнение с эталонными реализациями — 15 %, оригинальность и\nдополнительная работа — 15 %.</p>\n<blockquote>\n<p>Ячейки, помеченные <code># TODO</code>, нужно заполнить\nсамостоятельно. Ячейки с готовым кодом можно просто выполнить — они\nподготавливают данные и графики.</p>\n</blockquote>\n</div>\n<div id="db81966c" class="cell markdown">\n<h2 id="подготовка-окружения">Подготовка окружения</h2>\n</div>\n<div id="64dbd032" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> seaborn <span class="im">as</span> sns</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="op">%</span>matplotlib inline</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="dv">7</span>, <span class="dv">4</span>),</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a>sns.set_palette(<span class="st">&quot;viridis&quot;</span>)</span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span></span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> make_blobs, make_moons, make_circles, load_breast_cancer</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split, GridSearchCV</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.svm <span class="im">import</span> SVC</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>X_lin, y_lin <span class="op">=</span> make_blobs(n_samples<span class="op">=</span><span class="dv">80</span>, centers<span class="op">=</span><span class="dv">2</span>, cluster_std<span class="op">=</span><span class="fl">0.9</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>y_lin <span class="op">=</span> np.where(y_lin <span class="op">==</span> <span class="dv">0</span>, <span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>)          <span class="co"># для SVM метки удобнее в виде -1 / +1</span></span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a>plt.scatter(X_lin[:, <span class="dv">0</span>], X_lin[:, <span class="dv">1</span>], c<span class="op">=</span>y_lin, cmap<span class="op">=</span><span class="st">&quot;coolwarm&quot;</span>, edgecolor<span class="op">=</span><span class="st">&quot;k&quot;</span>, s<span class="op">=</span><span class="dv">45</span>)</span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>plt.title(<span class="st">&quot;Линейно разделимая выборка&quot;</span>)</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a>plt.show()</span></code></pre></div>\n</div>\n<div id="9cda636f" class="cell markdown">\n<h2 id="задание-1-двойственная-задача-линейного-svm">Задание 1.\nДвойственная задача линейного SVM</h2>\n<p>Двойственная задача:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><munder><mi>max</mi><mi>α</mi></munder><mspace width="0.222em"></mspace><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>α</mi><mi>i</mi></msub><mo>−</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><munder><mo>∑</mo><mrow><mi>i</mi><mo>,</mo><mi>j</mi></mrow></munder><msub><mi>α</mi><mi>i</mi></msub><msub><mi>α</mi><mi>j</mi></msub><msub><mi>y</mi><mi>i</mi></msub><msub><mi>y</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">⟨</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>x</mi><mi>j</mi></msub><mo stretchy="false" form="postfix">⟩</mo><mspace width="1.0em"></mspace><mtext mathvariant="normal">при</mtext><mspace width="1.0em"></mspace><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>α</mi><mi>i</mi></msub><msub><mi>y</mi><mi>i</mi></msub><mo>=</mo><mn>0</mn><mo>,</mo><mspace width="0.222em"></mspace><mspace width="0.222em"></mspace><mn>0</mn><mo>≤</mo><msub><mi>α</mi><mi>i</mi></msub><mo>≤</mo><mi>C</mi><mi>.</mi></mrow><annotation encoding="application/x-tex">\\max_{\\alpha}\\ \\sum_{i=1}^{n}\\alpha_i - \\frac{1}{2}\\sum_{i,j}\\alpha_i \\alpha_j y_i y_j \\langle x_i, x_j\\rangle\n\\quad \\text{при} \\quad \\sum_i \\alpha_i y_i = 0,\\ \\ 0 \\le \\alpha_i \\le C.</annotation></semantics></math></p>\n<p>Восстановление ответа:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>w</mi><mo>=</mo><msub><mo>∑</mo><mi>i</mi></msub><msub><mi>α</mi><mi>i</mi></msub><msub><mi>y</mi><mi>i</mi></msub><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">w = \\sum_i \\alpha_i y_i x_i</annotation></semantics></math>,\nа <strong>опорные векторы</strong> — объекты с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>α</mi><mi>i</mi></msub><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\alpha_i &gt; 0</annotation></semantics></math>.</p>\n<p>Решать будем через <code>scipy.optimize.minimize</code> (метод SLSQP\nподдерживает и равенства, и границы).</p>\n</div>\n<div id="6d05a580" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy.optimize <span class="im">import</span> minimize</span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> svm_dual_fit(X, y, C<span class="op">=</span><span class="fl">1.0</span>):</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Решение двойственной задачи линейного SVM.</span></span>\n<span id="cb2-5"><a href="#cb2-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-6"><a href="#cb2-6" aria-hidden="true" tabindex="-1"></a><span class="co">    Возвращает (alpha, w, b).</span></span>\n<span id="cb2-7"><a href="#cb2-7" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb2-8"><a href="#cb2-8" aria-hidden="true" tabindex="-1"></a>    n <span class="op">=</span> <span class="bu">len</span>(y)</span>\n<span id="cb2-9"><a href="#cb2-9" aria-hidden="true" tabindex="-1"></a>    K <span class="op">=</span> X <span class="op">@</span> X.T                       <span class="co"># матрица Грама для линейного ядра</span></span>\n<span id="cb2-10"><a href="#cb2-10" aria-hidden="true" tabindex="-1"></a>    P <span class="op">=</span> np.outer(y, y) <span class="op">*</span> K</span>\n<span id="cb2-11"><a href="#cb2-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-12"><a href="#cb2-12" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">:</span></span>\n<span id="cb2-13"><a href="#cb2-13" aria-hidden="true" tabindex="-1"></a>    <span class="co">#  1. objective(a)  = 0.5 * a @ P @ a - a.sum()      (минимизируем -L)</span></span>\n<span id="cb2-14"><a href="#cb2-14" aria-hidden="true" tabindex="-1"></a>    <span class="co">#  2. jac(a)        = P @ a - 1</span></span>\n<span id="cb2-15"><a href="#cb2-15" aria-hidden="true" tabindex="-1"></a>    <span class="co">#  3. ограничение   {&quot;type&quot;: &quot;eq&quot;, &quot;fun&quot;: lambda a: a @ y}</span></span>\n<span id="cb2-16"><a href="#cb2-16" aria-hidden="true" tabindex="-1"></a>    <span class="co">#  4. границы       [(0, C)] * n</span></span>\n<span id="cb2-17"><a href="#cb2-17" aria-hidden="true" tabindex="-1"></a>    <span class="co">#  5. res = minimize(objective, np.zeros(n), jac=jac, bounds=..., constraints=..., method=&quot;SLSQP&quot;)</span></span>\n<span id="cb2-18"><a href="#cb2-18" aria-hidden="true" tabindex="-1"></a>    <span class="co">#  6. w = ((alpha * y) @ X); b — по любому объекту с 0 &lt; alpha &lt; C</span></span>\n<span id="cb2-19"><a href="#cb2-19" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span></code></pre></div>\n</div>\n<div id="7a914a3e" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: найдите опорные векторы (alpha &gt; 1e-5) и визуализируйте:</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a><span class="co">#   - точки выборки, раскрашенные по классам;</span></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a><span class="co">#   - разделяющую прямую w @ x + b = 0;</span></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a><span class="co">#   - границы зазора w @ x + b = ±1 (пунктиром);</span></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a><span class="co">#   - опорные векторы — обведёнными крупными кружками.</span></span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a><span class="co"># Сравните w и b с SVC(kernel=&quot;linear&quot;, C=...).</span></span></code></pre></div>\n</div>\n<div id="2361790a" class="cell markdown">\n<h2 id="задание-2-ядра-на-нелинейных-данных">Задание 2. Ядра на\nнелинейных данных</h2>\n<p>Ядро позволяет работать в спрямляющем пространстве, не вычисляя само\nотображение:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>K</mi><mtext mathvariant="normal">lin</mtext></msub><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>z</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">⟨</mo><mi>x</mi><mo>,</mo><mi>z</mi><mo stretchy="false" form="postfix">⟩</mo><mo>,</mo><mspace width="2.0em"></mspace><msub><mi>K</mi><mtext mathvariant="normal">poly</mtext></msub><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>z</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">(</mo><mi>γ</mi><mo stretchy="false" form="prefix">⟨</mo><mi>x</mi><mo>,</mo><mi>z</mi><mo stretchy="false" form="postfix">⟩</mo><mo>+</mo><mi>r</mi><msup><mo stretchy="false" form="postfix">)</mo><mi>d</mi></msup><mo>,</mo><mspace width="2.0em"></mspace><msub><mi>K</mi><mtext mathvariant="normal">RBF</mtext></msub><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>z</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mi>exp</mi><mo>⁡</mo></mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mo>−</mo><mi>γ</mi><mo stretchy="false" form="postfix">∥</mo><mi>x</mi><mo>−</mo><mi>z</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">K_{\\text{lin}}(x, z) = \\langle x, z\\rangle, \\qquad\n  K_{\\text{poly}}(x, z) = (\\gamma\\langle x, z\\rangle + r)^d, \\qquad\n  K_{\\text{RBF}}(x, z) = \\exp\\bigl(-\\gamma\\|x - z\\|^2\\bigr).</annotation></semantics></math></p>\n</div>\n<div id="bb246376" class="cell code">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a>X_nl, y_nl <span class="op">=</span> make_moons(n_samples<span class="op">=</span><span class="dv">300</span>, noise<span class="op">=</span><span class="fl">0.25</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> plot_decision_boundary(model, X, y, ax, title):</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Готовая функция для отрисовки разделяющей поверхности.&quot;&quot;&quot;</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a>    h <span class="op">=</span> <span class="fl">0.02</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a>    x_min, x_max <span class="op">=</span> X[:, <span class="dv">0</span>].<span class="bu">min</span>() <span class="op">-</span> <span class="fl">0.5</span>, X[:, <span class="dv">0</span>].<span class="bu">max</span>() <span class="op">+</span> <span class="fl">0.5</span></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a>    y_min, y_max <span class="op">=</span> X[:, <span class="dv">1</span>].<span class="bu">min</span>() <span class="op">-</span> <span class="fl">0.5</span>, X[:, <span class="dv">1</span>].<span class="bu">max</span>() <span class="op">+</span> <span class="fl">0.5</span></span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a>    xx, yy <span class="op">=</span> np.meshgrid(np.arange(x_min, x_max, h), np.arange(y_min, y_max, h))</span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a>    zz <span class="op">=</span> model.decision_function(np.c_[xx.ravel(), yy.ravel()]).reshape(xx.shape)</span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-11"><a href="#cb4-11" aria-hidden="true" tabindex="-1"></a>    ax.contourf(xx, yy, zz, levels<span class="op">=</span><span class="dv">20</span>, cmap<span class="op">=</span><span class="st">&quot;coolwarm&quot;</span>, alpha<span class="op">=</span><span class="fl">0.7</span>)</span>\n<span id="cb4-12"><a href="#cb4-12" aria-hidden="true" tabindex="-1"></a>    ax.contour(xx, yy, zz, levels<span class="op">=</span>[<span class="dv">0</span>], colors<span class="op">=</span><span class="st">&quot;k&quot;</span>, linewidths<span class="op">=</span><span class="fl">1.5</span>)</span>\n<span id="cb4-13"><a href="#cb4-13" aria-hidden="true" tabindex="-1"></a>    ax.scatter(X[:, <span class="dv">0</span>], X[:, <span class="dv">1</span>], c<span class="op">=</span>y, cmap<span class="op">=</span><span class="st">&quot;coolwarm&quot;</span>, edgecolor<span class="op">=</span><span class="st">&quot;k&quot;</span>, s<span class="op">=</span><span class="dv">25</span>)</span>\n<span id="cb4-14"><a href="#cb4-14" aria-hidden="true" tabindex="-1"></a>    ax.set_title(title)</span>\n<span id="cb4-15"><a href="#cb4-15" aria-hidden="true" tabindex="-1"></a>    ax.grid(<span class="va">False</span>)</span></code></pre></div>\n</div>\n<div id="060bcbfd" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: обучите SVC с kernel=&quot;linear&quot; и kernel=&quot;rbf&quot; на make_moons,</span></span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       нарисуйте обе границы через plot_decision_boundary в одной строке subplots.</span></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       Повторите на make_circles. Какое ядро справляется и почему?</span></span></code></pre></div>\n</div>\n<div id="11b7d9ce" class="cell markdown">\n<h2 id="задание-3-подбор-c-и-gamma-через-gridsearchcv">Задание 3. Подбор\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>γ</mi><annotation encoding="application/x-tex">\\gamma</annotation></semantics></math>\nчерез GridSearchCV</h2>\n<ul>\n<li><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\n— штраф за ошибки: большое\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\n— узкий зазор и риск переобучения, малое — широкий зазор.</li>\n<li><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>γ</mi><annotation encoding="application/x-tex">\\gamma</annotation></semantics></math>\n— «радиус влияния» объекта в RBF: большое\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>γ</mi><annotation encoding="application/x-tex">\\gamma</annotation></semantics></math>\n— модель запоминает каждую точку.</li>\n</ul>\n</div>\n<div id="ce6ba8b5" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a>cancer <span class="op">=</span> load_breast_cancer()</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>Xc_train, Xc_test, yc_train, yc_test <span class="op">=</span> train_test_split(</span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a>    cancer.data, cancer.target, test_size<span class="op">=</span><span class="fl">0.3</span>, stratify<span class="op">=</span>cancer.target, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: соберите Pipeline(StandardScaler -&gt; SVC(kernel=&quot;rbf&quot;)) и запустите GridSearchCV</span></span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       по сетке C in [0.1, 1, 10, 100], gamma in [1e-3, 1e-2, 1e-1, 1], scoring=&quot;roc_auc&quot;, cv=5</span></span></code></pre></div>\n</div>\n<div id="2c3bbca9" class="cell markdown">\n<h2 id="задание-4-тепловая-карта-качества">Задание 4. Тепловая карта\nкачества</h2>\n<p>Постройте heatmap: строки —\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>,\nстолбцы —\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>γ</mi><annotation encoding="application/x-tex">\\gamma</annotation></semantics></math>,\nзначения — AUC на кросс-валидации. Отметьте оптимальную ячейку.</p>\n</div>\n<div id="0e15bec3" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: возьмите grid.cv_results_[&quot;mean_test_score&quot;], сделайте reshape по сетке</span></span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       и постройте sns.heatmap(..., annot=True, fmt=&quot;.3f&quot;)</span></span></code></pre></div>\n</div>\n<div id="bc8a20f0" class="cell markdown">\n<p><strong>Вывод:</strong> <em>как ведёт себя качество при слишком\nбольшом γ? Что это говорит о переобучении?</em></p>\n</div>\n<div id="b23c7caf" class="cell markdown">\n<h2 id="дополнительное-задание-полиномиальное-ядро-вручную">Дополнительное\nзадание. Полиномиальное ядро вручную</h2>\n<p>Реализуйте функцию\n<code>poly_kernel(X, Z, degree=3, gamma=1.0, coef0=1.0)</code> и\nподставьте её в <code>SVC(kernel=&lt;ваша функция&gt;)</code> (sklearn\nпринимает callable). Сравните с RBF по качеству и по времени\nобучения.</p>\n</div>\n<div id="1cd2e012" class="cell code">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> poly_kernel(X, Z, degree<span class="op">=</span><span class="dv">3</span>, gamma<span class="op">=</span><span class="fl">1.0</span>, coef0<span class="op">=</span><span class="fl">1.0</span>):</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">: (gamma * X @ Z.T + coef0) ** degree</span></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: SVC(kernel=poly_kernel) — обучите и сравните с SVC(kernel=&quot;rbf&quot;)</span></span></code></pre></div>\n</div>\n<div id="49680242" class="cell markdown">\n<h2 id="финальный-вывод">Финальный вывод</h2>\n<p><em>Напишите здесь связный вывод по работе (5–10\nпредложений):</em></p>\n<ul>\n<li>какие методы вы применили и почему;</li>\n<li>какие результаты получили в числах;</li>\n<li>где реализация «с нуля» разошлась с эталоном из <code>sklearn</code>\nи в чём причина;</li>\n<li>что бы вы улучшили, будь у вас больше времени.</li>\n</ul>\n</div>\n</body>\n</html>\n'}}]);